export interface LiveActivityStatus {
  app: string;
  title: string;
  doneTitle: string;
  details: string[];
  doneDetail: string;
  steps: string[];
  seconds: number;
  format?: "clock" | "minutes";
  glyph?: "render" | "delivery" | "deploy";
  lines?: string[];
}

export interface LiveActivityProps {
  status?: LiveActivityStatus;
  date?: string;
  /** Clock in the status bar and on the Lock Screen. */
  time?: string;
  /** Word under the countdown on the activity card. */
  remainingLabel?: string;
  accent?: string;
  /** Color of the headline lines; overrides the theme. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Hanken Grotesk by default. */
  fontFamily?: string;
  /** Size of the phone and lines, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "light" | "dark";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /**
   * Moves, trims or stretches the countdown, the camera's moves, single copy
   * lines and each gesture of the finger, by the ids in `./timeline`. Frames
   * on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<LiveActivityElementId>;
}

