/** Whether `at` changes between this frame and either neighbour. */
const moves = (
  at: (f: number) => number,
  f: number,
  step: number,
  eps = 1e-3,
) =>
  Math.abs(at(f + step) - at(f)) > eps || Math.abs(at(f) - at(f - step)) > eps;
const enterE = Easing.bezier(0.22, 1, 0.36, 1);
const exitE = Easing.bezier(0.55, 0, 1, 0.45);
