function fmtTime(sec: number, format: "clock" | "minutes") {
  if (format === "minutes") return `${Math.max(1, Math.ceil(sec / 60))} min`;
  const s = Math.max(0, Math.round(sec));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

function Ticker({
  value,
  prev,
  since,
  style,
}: {
  value: string;
  prev: string;
  since: number;
  style: React.CSSProperties;
}) {
  const glide = useGlide();
  const t = enterE(Math.min(1, since / 4));
  const chars = Array.from(value);
  const old = Array.from(prev.padStart(chars.length, " "));
  return (
    <span
      style={{
        display: "inline-flex",
        fontVariantNumeric: "tabular-nums",
        ...style,
      }}
    >
      {chars.map((ch, i) => {
        const changed = old[i] !== ch && prev.length === value.length;
        return (
          <span
            key={i}
            style={{
              position: "relative",
              display: "inline-block",
              whiteSpace: "pre",
              overflow: "hidden",
            }}
          >
            <span
              style={{
                display: "inline-block",
                // Every digit keeps its transform, rolled or not: a mark
                // that came and went with the roll would snap the digit.
                transform: `translateY(${changed ? (1 - t) * 45 : 0}%)${glide(changed && t < 1)}`,
                opacity: changed ? t : 1,
              }}
            >
              {ch}
            </span>
            {changed && t < 1 ? (
              <span
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  transform: `translateY(${-t * 45}%)${glide(t < 1)}`,
                  opacity: 1 - t,
                }}
              >
                {old[i]}
              </span>
            ) : null}
          </span>
        );
      })}
    </span>
  );
}

